function NoteBuilder(props:PlayProps){
 const {locale}=useT();const appearance=["pale ruby","deep ruby","pale lemon"],aromas=["fresh red fruit","ripe dark fruit","citrus","fresh herbs","violet","cedar"],conclusions=["best enjoyed young","can develop further","drink now"];const [look,setLook]=useState(""),[nose,setNose]=useState<string[]>([]),[structure,setStructure]=useState({acidity:3,tannin:2,body:3,sweetness:1,alcohol:3}),[conclusion,setConclusion]=useState(""),[done,setDone]=useState(false),[finalScore,setFinalScore]=useState(0),[start]=useState(Date.now());const finish=useFinish(props);const completed=(look?1:0)+(nose.length>=2?1:0)+1+(conclusion?1:0);const submit=()=>{const aromaFit=(look==="pale ruby"&&nose.includes("fresh red fruit"))||(look==="deep ruby"&&nose.includes("ripe dark fruit"))||(look==="pale lemon"&&(nose.includes("citrus")||nose.includes("fresh herbs")));const structureFit=(look==="pale lemon"&&structure.tannin<=1)||(look==="pale ruby"&&structure.body<=3)||(look==="deep ruby"&&structure.body>=3&&structure.tannin>=2);const coherent=aromaFit&&structureFit;const s=coherent?1000:700;setFinalScore(s);finish(s,coherent?5:4,5,0,start);setDone(true)};
 if(done)return <Result {...props} score={finalScore} correct={finalScore===1000?5:4} total={5} onReplay={props.onReplay} note={finalScore===1000?(locale==="de"?"Aussehen, Aromen und Struktur bilden ein plausibles Ganzes.":"Appearance, aromas and structure form a defensible whole."):(locale==="de"?"Einige Beobachtungen widersprechen sich. Eine helle Farbe und sehr hohes Tannin oder eine tiefe Farbe ohne Körper brauchen mehr Begründung.":"Some observations pull apart. Pale colour with very high tannin, or deep colour without body, needs stronger reasoning.")} profile={structure}/>;
 const fillClass=look==="deep ruby"?"fill-deep":look==="pale lemon"?"fill-lemon":"fill-pale";
 return <><PlayHeader gameId={props.gameId} round={completed} total={4} score={completed*180} practice={props.practice} onExit={props.onExit}/><div className="mx-auto max-w-5xl px-4 py-7"><p className="wine-kicker">{locale==="de"?"Eigenes, nicht-proprietäres Lernschema":"Original, non-proprietary learning framework"}</p><h1 className="mt-2 text-3xl font-black text-[var(--wine-cream)]">{locale==="de"?"Komponiere eine stimmige Tasting Note.":"Compose a coherent tasting note."}</h1>
  <div className="wine-note-workbench mt-7"><aside className="wine-note-visual"><div className={`wine-tasting-glass ${fillClass}`}><div className="wine-tasting-bowl"><i/></div><div className="wine-tasting-stem"/><div className="wine-tasting-foot"/></div><div className="wine-note-aromas">{nose.map((a,i)=><span key={a} style={{"--note-index":i} as React.CSSProperties}>{a}</span>)}</div></aside>
  <section className="wine-notebook"><fieldset><legend><span>01</span>{locale==="de"?"Aussehen":"Appearance"}</legend><div className="wine-segments">{appearance.map(v=><button type="button" key={v} onClick={()=>setLook(v)} className={look===v?"is-selected":""}>{v}</button>)}</div></fieldset>
   <fieldset><legend><span>02</span>{locale==="de"?"Nase · 2–3 wählen":"Nose · choose 2–3"}</legend><div className="flex flex-wrap gap-2">{aromas.map(v=><button type="button" key={v} onClick={()=>setNose(s=>s.includes(v)?s.filter(x=>x!==v):s.length<3?[...s,v]:s)} className={`wine-aroma-token family-${aromaFamily(v)} ${nose.includes(v)?"is-selected":""}`}>{v}</button>)}</div></fieldset>
   <fieldset><legend><span>03</span>{locale==="de"?"Struktur":"Structure"}</legend><div className="wine-structure-controls">{Object.entries(structure).map(([key,value])=><label key={key}><span>{key}<b>{value}/5</b></span><input aria-label={key} type="range" min="1" max="5" step="1" value={value} onChange={e=>setStructure(s=>({...s,[key]:Number(e.target.value)}))}/></label>)}</div></fieldset>
   <fieldset><legend><span>04</span>{locale==="de"?"Schluss":"Conclusion"}</legend><div className="wine-segments">{conclusions.map(v=><button type="button" key={v} onClick={()=>setConclusion(v)} className={conclusion===v?"is-selected":""}>{v}</button>)}</div></fieldset>
  </section></div><button disabled={!look||nose.length<2||!conclusion} onClick={submit} className="wine-button mt-7">{locale==="de"?"Notiz prüfen":"Review note"}</button>
 </div></>;
}
function ServiceChallenge(props:PlayProps){
 const {locale}=useT();const scenario=SERVICE_SCENARIOS[props.seed%SERVICE_SCENARIOS.length];const decisions:ServiceDecision[]=["glass","temperature","decant","first-step"];const [step,setStep]=useState(0),[answers,setAnswers]=useState<Partial<Record<ServiceDecision,string>>>({}),[correct,setCorrect]=useState(0),[reviewed,setReviewed]=useState(false),[done,setDone]=useState(false),[start]=useState(Date.now());const finish=useFinish(props),encounter=useWineDex(s=>s.encounter);const choiceSets:Record<ServiceDecision,{id:string;label:{en:string;de:string}}[]>={
  glass:[{id:"tulip",label:{en:"Tulip sparkling glass",de:"Tulpenförmiges Schaumweinglas"}},{id:"medium-white",label:{en:"Medium white-wine glass",de:"Mittleres Weißweinglas"}},{id:"medium-red",label:{en:"Medium red-wine glass",de:"Mittleres Rotweinglas"}},{id:"large-red",label:{en:"Large red-wine glass",de:"Großes Rotweinglas"}},{id:"small-sweet",label:{en:"Small sweet-wine glass",de:"Kleines Süßweinglas"}}],
  temperature:[{id:"well-chilled",label:{en:"Well chilled",de:"Gut gekühlt"}},{id:"cool",label:{en:"Cool",de:"Kühl"}},{id:"lightly-chilled",label:{en:"Lightly chilled",de:"Leicht gekühlt"}},{id:"cellar-cool",label:{en:"Cellar-cool",de:"Kellerkühl"}}],
  decant:[{id:"no",label:{en:"Usually no",de:"Meist nein"}},{id:"optional",label:{en:"Conditionally defensible",de:"Situativ vertretbar"}},{id:"yes",label:{en:"Often defensible",de:"Häufig vertretbar"}}],
  "first-step":[{id:"present",label:{en:"Present and confirm the bottle first",de:"Flasche zuerst präsentieren und bestätigen"}},{id:"open",label:{en:"Open immediately",de:"Sofort öffnen"}},{id:"pour",label:{en:"Pour every glass first",de:"Zuerst alle Gläser füllen"}}],
 };const labels:Record<ServiceDecision,{en:string;de:string}>={glass:{en:"Choose the glass",de:"Wähle das Glas"},temperature:{en:"Set the temperature band",de:"Wähle den Temperaturbereich"},decant:{en:"Assess decanting",de:"Bewerte Dekantieren"},"first-step":{en:"Choose the first service step",de:"Wähle den ersten Serviceschritt"}};const select=(value:string)=>{const key=decisions[step],ok=value===scenario.answers[key];setAnswers(a=>({...a,[key]:value}));if(ok)setCorrect(c=>c+1);if(step===3)setReviewed(true);else setStep(s=>s+1)};const finalize=()=>{const score=correct*250;finish(score,correct,4,correct,start);if(!props.practice)encounter(scenario.id,"style",props.gameId,correct>=3);setDone(true)};
 if(done)return <Result {...props} score={correct*250} correct={correct} total={4} onReplay={props.onReplay}/>;
 const tempIndex=["well-chilled","cool","lightly-chilled","cellar-cool"].indexOf(answers.temperature??"cool");
 return <><PlayHeader gameId={props.gameId} round={reviewed?4:step+1} total={4} score={correct*250} practice={props.practice} onExit={props.onExit}/><div className="mx-auto max-w-5xl px-4 py-7"><p className="wine-kicker">{locale==="de"?"Service-Station · rein pädagogische Übung":"Service station · educational practice only"}</p><h1 className="mt-2 text-3xl font-black text-[var(--wine-cream)]">{localize(scenario.title,locale)}</h1><p className="mt-2 text-sm text-[var(--wine-muted)]">{localize(scenario.context,locale)} · {locale==="de"?"Kein Alkoholkonsum erforderlich oder empfohlen.":"No alcohol consumption is required or encouraged."}</p>
  <div className="wine-service-station mt-6"><div className="wine-service-table"><span className="service-plate"/><span className={`service-glass glass-${answers.glass??"unset"}`}><i/></span><span className="service-bottle"><i/></span>{answers.decant&&answers.decant!=="no"&&<span className="service-decanter"/>}<span className="service-napkin"/></div><div className="wine-service-gauge"><span>{locale==="de"?"Temperatur":"Temperature"}</span><div><i style={{height:`${25+tempIndex*20}%`}}/></div><b>{answers.temperature?localize(choiceSets.temperature.find(x=>x.id===answers.temperature)!.label,locale):"—"}</b></div><ol className="wine-service-rail">{decisions.map((d,i)=><li key={d} className={`${i<step||reviewed?"is-done":""} ${i===step&&!reviewed?"is-current":""}`}><span>{String(i+1).padStart(2,"0")}</span>{localize(labels[d],locale)}{answers[d]&&<Check className="h-4 w-4"/>}</li>)}</ol></div>
  {!reviewed?<section className="mt-6"><p className="wine-kicker">{localize(labels[decisions[step]],locale)}</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{choiceSets[decisions[step]].map(c=><button key={c.id} aria-pressed={answers[decisions[step]]===c.id} onClick={()=>select(c.id)} className="wine-answer">{localize(c.label,locale)}<ArrowRight className="h-4 w-4"/></button>)}</div></section>:<div className="wine-reveal"><p className="font-bold">{correct}/4 {locale==="de"?"Serviceentscheidungen stimmig":"service decisions aligned"}</p><p className="mt-2 text-sm text-[var(--wine-muted)]">{localize(scenario.explanation,locale)}</p><div className="mt-3 grid gap-1 text-xs">{decisions.map(d=><p key={d}><b>{localize(labels[d],locale)}:</b> {localize(choiceSets[d].find(x=>x.id===scenario.answers[d])!.label,locale)}</p>)}</div><button onClick={finalize} className="wine-button mt-4">{locale==="de"?"Service abschließen":"Complete service"}<Check className="h-4 w-4"/></button></div>}
 </div></>;
}
function ProfileMeter({label,value}:{label:string;value:number}){return <div className="wine-profile-meter"><span>{label}<b>{value}/5</b></span><div>{Array.from({length:5},(_,i)=><i key={i} className={i<value?"is-on":""}/>)}</div></div>}
function Result(props:PlayProps&{score:number;correct:number;total:number;onReplay:()=>void;note?:string;profile?:Record<string,number>}){
 const {locale}=useT();const accuracy=Math.round(props.correct/Math.max(1,props.total)*100);return <div className="mx-auto max-w-3xl px-4 py-12 md:py-20"><p className="wine-kicker">{props.practice?(locale==="de"?"Übungsrunde beendet":"Practice complete"):(locale==="de"?"Kellerpass gestempelt":"Cellar passport stamped")}</p><h1 className="mt-3 text-5xl font-black tracking-[-.05em] text-[var(--wine-cream)]">{props.score} <span className="text-2xl text-[var(--wine-copper)]">pts</span></h1><div className="mt-8 grid grid-cols-2 gap-3"><div className="wine-stat"><span>{props.correct}/{props.total}</span><small>{locale==="de"?"stimmig":"defensible"}</small></div><div className="wine-stat"><span>{accuracy}%</span><small>{locale==="de"?"Genauigkeit":"accuracy"}</small></div></div>{props.profile&&<div className="wine-profile-panel mt-5"><p className="wine-kicker">{locale==="de"?"Dein visuelles Weinprofil":"Your visual wine profile"}</p>{Object.entries(props.profile).map(([key,value])=><ProfileMeter key={key} label={key} value={value}/>)}</div>}{props.note&&<p className="wine-reveal">{props.note}</p>}<p className="mt-6 text-sm leading-6 text-[var(--wine-muted)]">{props.practice?(locale==="de"?"Wie versprochen wurde nichts gespeichert.":"As promised, nothing was saved."):(locale==="de"?"XP, Kompetenzfortschritt und neue Wine-Dex-Begegnungen wurden separat gespeichert.":"XP, competency progress and new Wine-Dex encounters were saved separately.")}</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={props.onReplay} className="wine-button"><RotateCcw className="h-4 w-4"/>{locale==="de"?"Nochmal":"Play again"}</button><Link href="/wine-nerds" className="wine-button wine-button-quiet">{locale==="de"?"Zum Keller":"Wine cellar"}</Link></div></div>
}
